    if (family === 6 && model >= 22 && model <= 29) return "Core (Penryn)";
    if (family === 6 && model >= 30 && model <= 34) return "Nehalem";
    if (family === 6 && model >= 37 && model <= 44) return "Westmere";
    if (family === 6 && model >= 42 && model <= 47) return "Sandy Bridge";
