function generateWaveformSVG(samples, width = 800, height = 128, color2 = "#8b5cf6", style = "bars") {
  const barCount = Math.min(samples.length, 200);
  const step = Math.floor(samples.length / barCount);
  const barWidth = width / barCount;
  const gap = barWidth * 0.2;
  if (style === "line") {
    const points = samples.filter((_, i) => i % step === 0).map((v, i) => `${i / barCount * width},${height - v * height * 0.9}`).join(" ");
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}"><polyline points="${points}" fill="none" stroke="${color2}" stroke-width="2" stroke-linejoin="round"/></svg>`;
  }
  if (style === "mirror") {
    const bars2 = samples.filter((_, i) => i % step === 0).map((v, i) => {
      const x = i * barWidth + gap / 2;
      const h = v * height * 0.8;
      const bw = barWidth - gap;
      return `<rect x="${x}" y="${height / 2 - h / 2}" width="${bw}" height="${h}" rx="1" fill="${color2}" opacity="0.8"/>`;
    }).join("");
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}"><line x1="0" y1="${height / 2}" x2="${width}" y2="${height / 2}" stroke="${color2}" stroke-width="1" opacity="0.3"/>${bars2}</svg>`;
  }
  const bars = samples.filter((_, i) => i % step === 0).map((v, i) => {
    const x = i * barWidth + gap / 2;
    const h = v * height * 0.9;
    const bw = barWidth - gap;
    return `<rect x="${x}" y="${height - h}" width="${bw}" height="${h}" rx="1" fill="${color2}" opacity="0.8"/>`;
  }).join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}">${bars}</svg>`;
}
function generateThumbnailSVG(title, width = 1280, height = 720, bgColor = "#667eea", bgColor2 = "#764ba2", titleColor = "#ffffff", titleSize = 64) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}">
  <defs>
    <linearGradient id="bg" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="${bgColor}"/>
      <stop offset="100%" stop-color="${bgColor2}"/>
    </linearGradient>
  </defs>
  <rect width="${width}" height="${height}" fill="url(#bg)"/>
  <text x="${width / 2}" y="${height / 2 + titleSize * 0.35}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${titleSize}" font-weight="bold" fill="${titleColor}">${escapeXml2(title)}</text>
</svg>`;
}
function escapeXml2(str2) {
  return str2.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}

