async function approvalsGate(input) {
  const gate = getApprovalGate();
  try {
    switch (input.action) {
      case "submit": {
        if (!input.title || !input.toolId || !input.risk)
          return { success: false, error: 'submit requires "title", "toolId", "risk"' };
        const r = gate.submit({
          title: input.title,
          toolId: input.toolId,
          actionSummary: input.actionSummary ?? "",
          risk: input.risk,
          requestedBy: input.requestedBy ?? "agent",
          ...input.runId ? { runId: input.runId } : {}
        });
        return { success: true, data: { requestId: r.id, status: r.status } };
      }
      case "decide":
        return {
          success: gate.decide(input.requestId, input.decision ?? "approved", input.by ?? "human"),
          data: null
        };
      case "pending":
        return { success: true, data: { queue: gate.compact() } };
      case "history":
        return { success: true, data: gate.history() };
      case "policy": {
        const { BALANCED_POLICY: BALANCED_POLICY2, STRICT_POLICY: STRICT_POLICY2, AUTONOMOUS_POLICY: AUTONOMOUS_POLICY2 } = await Promise.resolve().then(() => (init_approvals(), approvals_exports));
        if (input.preset === "strict") gate.setPolicy(STRICT_POLICY2);
        else if (input.preset === "autonomous") gate.setPolicy(AUTONOMOUS_POLICY2);
        else if (input.preset === "balanced") gate.setPolicy(BALANCED_POLICY2);
        return { success: true, data: { policy: gate.getPolicy() } };
      }
      case "expire":
        return { success: true, data: { expired: gate.expireStale() } };
      default:
        return { success: false, error: `Unknown action "${input.action}"` };
    }
  } catch (e) {
    return { success: false, error: e instanceof Error ? e.message : String(e) };
  }
}
