var inferenceRouterExecutor = async (input) => {
  const mode2 = input.mode ?? "balanced";
  const workloadType = input.workloadType ?? "general";
  const forceRebenchmark = input.forceRebenchmark;
  const router = await getInferenceRouter();
  if (forceRebenchmark) {
    await router.rebenchmark();
  }
  const decision = await router.selectBackend(
    mode2,
    workloadType
  );
  const sysInfo = router.getSystemInfo();
  const optimizationPlan = buildOptimizationPlan(decision.backend, mode2, sysInfo);
  return {
    success: true,
    data: {
      decision,
      optimization: {
        backend: optimizationPlan.backend,
        expectedSpeedup: optimizationPlan.expectedSpeedup,
        optimizations: optimizationPlan.optimizations.map((o) => ({
          name: o.name,
          description: o.description,
          speedup: o.estimatedSpeedup,
          risk: o.riskLevel
        }))
      },
      systemInfo: {
        platform: sysInfo.platform,
        arch: sysInfo.arch,
        ramGB: Math.round(sysInfo.totalRamBytes / (1024 * 1024 * 1024)),
        cpu: sysInfo.cpuBrand
      }
    }
  };
};
