var catalogExecutor = async (input) => {
  const action = input.action ?? "list";
  if (action === "get" && input.toolId) {
    const entry2 = CATALOG_ENTRIES.find((e) => e.id === input.toolId);
    return {
      success: !!entry2,
      data: entry2 ?? { error: `Tool '${input.toolId}' not found in catalog` }
    };
  }
  let results = [...CATALOG_ENTRIES];
  if (input.category) {
    results = results.filter((e) => e.catalogCategory === input.category);
  }
  if (input.query) {
    const q = input.query.toLowerCase();
    results = results.filter(
      (e) => e.name.toLowerCase().includes(q) || e.description.toLowerCase().includes(q) || e.tags.some((t) => t.toLowerCase().includes(q))
    );
  }
  return {
    success: true,
    data: {
      total: results.length,
      tools: results.map((e) => ({
        id: e.id,
        name: e.name,
        category: e.catalogCategory,
        tags: e.tags,
        llmBased: e.isLLMBased
      }))
    }
  };
};
