  let nodeId = 0;
  for (let j = 0; j <= ny; j++) {
    for (let i = 0; i <= nx; i++) {
      nodes.push({
        id: nodeId++,
        x: i / nx * width,
        y: j / ny * height,
        dofPerNode
      });
    }
  }
  let elemId = 0;
  for (let j = 0; j < ny; j++) {
    for (let i = 0; i < nx; i++) {
      const n1 = j * (nx + 1) + i;
      const n2 = n1 + 1;
      const n3 = n2 + (nx + 1);
      const n4 = n1 + (nx + 1);
      elements.push({
        id: elemId++,
        type: "q4",
        nodeIds: [n1, n2, n3, n4],
        material,
        thickness
      });
    }
  }
  return { nodes, elements, nDOF: nodes.length * dofPerNode };
