function createCSTMesh(width, height, nx, ny, material, thickness = 1) {
  const nodes = [];
  const elements = [];
  const dofPerNode = 2;
  let nodeId = 0;
  for (let j = 0; j <= ny; j++) {
    for (let i = 0; i <= nx; i++) {
      nodes.push({
        id: nodeId++,
        x: i / nx * width,
        y: j / ny * height,
        dofPerNode
      });
    }
  }
  let elemId = 0;
  for (let j = 0; j < ny; j++) {
    for (let i = 0; i < nx; i++) {
      const bl = j * (nx + 1) + i;
      const br = bl + 1;
      const tl = bl + (nx + 1);
      const tr = tl + 1;
      elements.push({ id: elemId++, type: "cst", nodeIds: [bl, br, tr], material, thickness });
      elements.push({ id: elemId++, type: "cst", nodeIds: [bl, tr, tl], material, thickness });
    }
  }
  return { nodes, elements, nDOF: nodes.length * dofPerNode };
}

