function feaSolve(input) {
  const cfg = input;
  const problemType = cfg.problemType || "plane-stress";
  const w = cfg.width || 1;
  const h = cfg.height || 1;
  const nx = cfg.nx || 10;
  const ny = cfg.ny || 10;
  const E = cfg.E || 21e10;
  const nu = cfg.nu || 0.3;
  const thickness = cfg.thickness || 1;
  const loads = cfg.loads || [];
  const fixedEdges = cfg.fixedEdges || ["left"];
  const material = { E, nu };
  const mesh = cfg.problemType === "cst" ? createCSTMesh(w, h, nx, ny, material, thickness) : createRectangularMesh(w, h, nx, ny, material, thickness);
  const bcs = [];
  for (const edge of fixedEdges) {
    for (const node2 of mesh.nodes) {
      if (edge === "left" && node2.x < w / nx / 2) {
        bcs.push({ nodeId: node2.id, dof: 0, type: "displacement", value: 0 });
        bcs.push({ nodeId: node2.id, dof: 1, type: "displacement", value: 0 });
      }
      if (edge === "right" && node2.x > w - w / nx / 2) {
        bcs.push({ nodeId: node2.id, dof: 0, type: "displacement", value: 0 });
        bcs.push({ nodeId: node2.id, dof: 1, type: "displacement", value: 0 });
      }
      if (edge === "bottom" && node2.y < h / ny / 2) {
        bcs.push({ nodeId: node2.id, dof: 0, type: "displacement", value: 0 });
        bcs.push({ nodeId: node2.id, dof: 1, type: "displacement", value: 0 });
      }
      if (edge === "top" && node2.y > h - h / ny / 2) {
        bcs.push({ nodeId: node2.id, dof: 0, type: "displacement", value: 0 });
        bcs.push({ nodeId: node2.id, dof: 1, type: "displacement", value: 0 });
      }
    }
  }
  for (const load2 of loads) {
    const nearest = mesh.nodes.reduce((best, node2) => {
      const d = Math.hypot(node2.x - load2.nodeX, node2.y - load2.nodeY);
      return d < best.d ? { node: node2, d } : best;
    }, { node: mesh.nodes[0], d: Infinity });
    bcs.push({ nodeId: nearest.node.id, dof: 0, type: "force", value: load2.fx || 0 });
    bcs.push({ nodeId: nearest.node.id, dof: 1, type: "force", value: load2.fy || 0 });
  }
  const result = solveFEA(mesh, bcs, problemType !== "plane-strain");
  return {
    success: true,
    data: {
      maxDisplacement: result.maxDisplacement,
      maxStress: result.maxStress,
      converged: result.converged,
      nNodes: mesh.nodes.length,
      nElements: mesh.elements.length,
      nDOF: mesh.nDOF,
      elementStresses: result.elementStresses.slice(0, 20).map((es) => ({
        elementId: es.elementId,
        vonMises: es.vonMises,
        stress: es.stress
      })),
      summary: `FEA solved: ${mesh.elements.length} elements, max displacement=${result.maxDisplacement.toExponential(3)}m, max stress=${result.maxStress.toExponential(3)}Pa`
    }
  };
}
