function optimize(input) {
  const cfg = input;
  const method = cfg.method;
  const x0 = cfg.x0 || [0, 0];
  const rosenbrock = (x) => (1 - x[0]) ** 2 + 100 * (x[1] - x[0] ** 2) ** 2;
  let result;
  switch (method) {
    case "gradient-descent":
      result = gradientDescent(rosenbrock, x0, {
        learningRate: cfg.learningRate || 1e-3,
        maxIter: cfg.maxIter || 500,
        tolerance: cfg.tolerance || 1e-8,
        adaptiveLR: true
      });
      break;
    case "newton":
      result = newtonOptimize(rosenbrock, x0, {
        maxIter: cfg.maxIter || 100,
        tolerance: cfg.tolerance || 1e-10
      });
      break;
    case "bfgs":
      result = bfgsOptimize(rosenbrock, x0, {
        maxIter: cfg.maxIter || 500,
        tolerance: cfg.tolerance || 1e-8
      });
      break;
    default:
      result = bfgsOptimize(rosenbrock, x0);
  }
  return {
    success: true,
    data: {
      method,
      solution: result.solution,
      objectiveValue: result.objectiveValue,
      iterations: result.iterations,
      converged: result.converged,
      summary: `${method}: x=${result.solution.map((v) => v.toFixed(6)).join(", ")}, f=${result.objectiveValue.toExponential(3)}, ${result.converged ? "converged" : "not converged"} in ${result.iterations} iterations`
    }
  };
}
