async function graphRun(input) {
  const channels = input.channels ?? ["topic", "draft", "reviewScore", "revision"];
  const topic = input.variables?.topic;
  const graph = new StateGraph(
    input.name ?? "draft-review"
  );
  for (const c2 of channels) graph.channel(c2);
  graph.addNode("draft", (state) => ({ draft: `Draft about ${state.topic}`, revision: 1 })).addNode("review", (state) => ({
    reviewScore: Math.max(0, 10 - state.revision * 3)
  })).addNode("revise", (state) => ({ revision: state.revision + 1 }));
  graph.addEdge(START, "draft");
  graph.addEdge("draft", "review");
  graph.addConditionalEdge(
    "review",
    (state) => state.reviewScore >= 7 || state.revision >= 3 ? END : "revise"
  );
  graph.addEdge("revise", "review");
  const compiled = graph.compile({ recursionLimit: input.recursionLimit ?? 25 });
  const events = [];
  try {
    const result = await compiled.invoke(
      { topic: topic ?? "stitap orchestration" },
      { stream: (e) => events.push({ type: e.type, node: "node" in e ? e.node : void 0 }) }
    );
    return {
      success: true,
      data: {
        backend: activeBackend(),
        finalState: result.state,
        trace: result.trace,
        events
      }
    };
  } catch (err) {
    return { success: false, error: err instanceof Error ? err.message : String(err) };
  }
}

