async function sessionModules(input) {
  const action = input.action;
  let state = createSessionState("balanced");
  switch (action) {
    case "list": {
      return {
        success: true,
        data: MODULE_REGISTRY.map((m) => ({
          id: m.id,
          name: m.name,
          category: m.category,
          on: state.enabled[m.id],
          offline: m.offline,
          overhead: m.contextOverheadTokens,
          requires: m.requires
        }))
      };
    }
    case "enable": {
      if (!input.moduleId) return { success: false, error: 'Missing "moduleId"' };
      state = setModuleEnabled(state, input.moduleId, true);
      break;
    }
    case "disable": {
      if (!input.moduleId) return { success: false, error: 'Missing "moduleId"' };
      state = setModuleEnabled(state, input.moduleId, false);
      break;
    }
    case "preset": {
      if (!input.preset) return { success: false, error: 'Missing "preset"' };
      state = applyPreset(state, input.preset);
      break;
    }
    case "budget":
      break;
    default:
      return { success: false, error: `Unknown action "${action}"` };
  }
  const budget = computeBudget(state, { modelContextWindow: input.modelContextWindow });
  return { success: true, data: { profile: state.profile, ...budget } };
}
