function matrixCalc(input) {
  const cfg = input;
  const A = cfg.matrix;
  const op = cfg.operation;
  if (!A || !A.length) return { success: false, data: "No matrix provided" };
  try {
    switch (op) {
      case "determinant":
        return { success: true, data: { determinant: matrixDet(A), size: `${A.length}\xD7${A[0].length}` } };
      case "inverse":
        return { success: true, data: { inverse: matrixInverse(A), size: `${A.length}\xD7${A[0].length}` } };
      case "trace": {
        const trace = A.reduce((s, row, i) => s + (row[i] || 0), 0);
        return { success: true, data: { trace, size: `${A.length}\xD7${A[0].length}` } };
      }
      case "transpose": {
        const n = A.length, m = A[0].length;
        const T = Array.from({ length: m }, (_, j) => Array.from({ length: n }, (_2, i) => A[i][j]));
        return { success: true, data: { transpose: T, size: `${m}\xD7${n}` } };
      }
      default:
        return { success: false, data: `Unknown operation: ${op}` };
    }
  } catch (e) {
    return { success: false, data: `Error: ${e instanceof Error ? e.message : String(e)}` };
  }
}
